/** Browser File/Blob/XHR + actual client and session service + local PostgreSQL.
 * Only HTTP authentication and the S3 endpoint are synthetic boundaries. */
import assert from "node:assert/strict";
import { createServer } from "node:http";
import { once } from "node:events";
import { randomUUID } from "node:crypto";
import { readFileSync, writeFileSync } from "node:fs";
import ts from "typescript";
import { eq, inArray } from "drizzle-orm";
import { chromium, firefox, webkit, type Browser } from "playwright";
import { startS3MultipartEmulator } from "./helpers/s3-multipart-emulator.mjs";
const {url}=JSON.parse(readFileSync(".data/qa-database.json","utf8")) as {url:string};
if(new URL(url).hostname!=="127.0.0.1" || new URL(url).pathname!=="/maras_qa" || process.env.S3_BUCKET || process.env.S3_ENDPOINT) throw new Error("Dedicated loopback QA only; no storage credentials allowed");
const s3=await startS3MultipartEmulator();
Object.assign(process.env,{DATABASE_URL:url,DATABASE_SSL:"false",S3_ENDPOINT:s3.endpoint,S3_BUCKET:s3.bucket,S3_ACCESS_KEY_ID:s3.accessKey,S3_SECRET_ACCESS_KEY:s3.secretKey,S3_FORCE_PATH_STYLE:"true",S3_ALLOW_INSECURE_LOOPBACK:"true",S3_MULTIPART_ENABLED:"true",NODE_ENV:"test"});
const {getDb,closeDb}=await import("../db/index"), schema=await import("../db/schema"), service=await import("../lib/video-upload-sessions");
const db=getDb(), tag=`qa-browser-resume-${randomUUID()}`, checks:string[]=[], ownerIds:number[]=[];
const engines=(process.env.QA_BROWSERS||"chromium").split(",");
let ownerId=0, pause=false, pauseSeen=false, feature=true;
const modules: Record<string,string> = {};
for(const name of ["resumable-video-upload","video-upload-policy","upload-client","admin-client"]) {
  const javascript=ts.transpileModule(readFileSync(`lib/${name}.ts`,"utf8"),{compilerOptions:{module:ts.ModuleKind.ESNext,target:ts.ScriptTarget.ES2022}}).outputText;
  modules[`/${name}.js`]=javascript.replace(/"@\/lib\/([^\"]+)"/g,'"/$1.js"');
}
modules["/interaction-events.js"]='export const notify=()=>{}; export const requestAdminVerification=async()=>false;';
const server=createServer(async(req,res)=>{
  try {
    const path=new URL(req.url!,"http://127.0.0.1").pathname;
    if(modules[path]) {res.writeHead(200,{"content-type":"text/javascript"});res.end(modules[path]);return;}
    const json=(value:unknown,status=200)=>{res.writeHead(status,{"content-type":"application/json","cache-control":"no-store"});res.end(JSON.stringify(value));};
    if(path==="/api/admin/me") return json({user:{id:ownerId}});
    if(path==="/api/admin/videos/multipart" && req.method==="POST") {
      let raw="";for await(const chunk of req){raw+=chunk.toString();if(raw.length>32768)throw new Error("body bound");}
      const p=JSON.parse(raw); if(req.headers["x-meras-acting-user"]!==String(ownerId)) return json({error:"fixture actor mismatch"},403);
      if(!feature) return json({code:"MULTIPART_NOT_ENABLED"},503);
      if(p.action==="sign" && p.partNumber===2 && pause){pauseSeen=true; const timer=setTimeout(()=>json({error:"paused"},503),5000);res.on("close",()=>clearTimeout(timer));return;}
      try {
        if(p.action==="start")return json({upload:await service.startVideoUpload(ownerId,p)});
        if(p.action==="status")return json({upload:await service.getVideoUpload(ownerId,p.id)});
        if(p.action==="sign")return json({part:await service.signVideoUploadPart(ownerId,p.id,p.partNumber)});
        if(p.action==="complete")return json({upload:await service.completeVideoUpload(ownerId,p.id)});
        if(p.action==="abort"){await service.abortVideoUpload(ownerId,p.id);return json({ok:true});}
        return json({error:"unknown"},400);
      }catch(error){return json({error:error instanceof Error?error.message:"failed"},error instanceof service.VideoUploadError?error.status:500);}
    }
    res.writeHead(200,{"content-type":"text/html; charset=utf-8"});res.end(`<!doctype html><html lang="ar" dir="rtl"><meta charset="utf-8"><title>قبول الرفع القابل للاستئناف</title><body><h1>اختبار الرفع الآمن</h1><p id="status">جاهز</p><progress id="progress" max="100" value="0"></progress><script type="module">
import {uploadResumableVideo} from '/resumable-video-upload.js';
window.begin = () => {
 window.controller = new AbortController(); window.progresses=[];
 const bytes=new Uint8Array(8*1024*1024+1000); bytes.fill(97); bytes.set(new TextEncoder().encode('0000ftypisom'));
 window.file=new File([bytes],'fixture.mp4',{type:'video/mp4'});
 window.work=uploadResumableVideo({file:window.file,courseSlug:'${tag}',lessonId:'browser',contentType:'video/mp4',signal:window.controller.signal,
 onProgress:p=>{window.progresses.push(p);document.querySelector('#progress').value=p.percent;},onStatus:m=>{document.querySelector('#status').textContent=m;}})
 .then(result=>{window.result=result;return {ok:true,status:result?.status,id:result?.id,key:result?.objectKey,fallback:result===null};},error=>({ok:false,aborted:window.controller.signal.aborted,error:error.message}));
}; window.ready=true;
</script></body></html>`);
  }catch{if(!res.headersSent){res.writeHead(500);res.end();}else res.destroy();}
});
server.listen(0,"127.0.0.1");await once(server,"listening");const address=server.address();if(!address || typeof address==="string")throw new Error("listener missing");const origin=`http://127.0.0.1:${address.port}`;
type BrowserResult = { ok: boolean; aborted?: boolean; status?: string; id?: string; key?: string; fallback?: boolean; error?: string };
let browser:Browser|undefined;
try{
 for(const engine of engines){
  assert.ok(["chromium","firefox","webkit"].includes(engine));
  const [owner]=await db.insert(schema.users).values({email:`${tag}-${engine}@example.test`,fullName:"Synthetic browser owner",passwordHash:"not-a-login",role:"supervisor"}).returning({id:schema.users.id});ownerId=owner.id;ownerIds.push(owner.id);
  const factory={chromium,firefox,webkit}[engine as "chromium"|"firefox"|"webkit"];
  browser=await factory.launch({headless:true,...(engine==="chromium" && process.env.QA_CHROMIUM_EXECUTABLE?{executablePath:process.env.QA_CHROMIUM_EXECUTABLE,args:["--no-sandbox"]}:{})});
  const page=await browser.newPage(), errors:string[]=[];page.on("pageerror",error=>errors.push(error.message));
  await page.goto(origin);await page.waitForFunction(()=>Boolean((window as Window & {ready?:boolean}).ready));
  pause=true;pauseSeen=false;feature=true;
  await page.evaluate("begin()");
  const deadline=Date.now()+15000;while(!pauseSeen && Date.now()<deadline)await new Promise(r=>setTimeout(r,30));assert.equal(pauseSeen,true,"first part must commit before pausing the second");
  await page.evaluate("controller.abort()");assert.equal((await page.evaluate<BrowserResult>("work")).aborted,true);
  const cached=await page.evaluate("Object.values(localStorage)") as string[];assert.equal(cached.length,1);
  assert.ok(!cached.join("").includes("X-Amz") && !cached.join("").includes(s3.secretKey));
  const [session]=await db.select().from(schema.videoUploadSessions).where(eq(schema.videoUploadSessions.userId,ownerId));
  assert.deepEqual((await service.getVideoUpload(ownerId,session.id)).completedParts,[1]);
  pause=false;await page.reload();await page.waitForFunction(()=>Boolean((window as Window & {ready?:boolean}).ready));
  await page.evaluate("begin()");const result=await page.evaluate<BrowserResult>("work");assert.equal(result.ok,true,result.error);assert.equal(result.id,session.id);assert.equal(result.status,"uploaded");
  const puts=s3.requests.filter(req=>req.method==="PUT" && req.path.endsWith(session.objectKey));
  assert.equal(puts.filter(req=>req.part==="1").length,1);assert.equal(puts.filter(req=>req.part==="2").length,1);
  assert.equal(s3.objects.get(session.objectKey).body.length,8*1024*1024+1000);
  const progress=await page.evaluate("progresses") as Array<{loaded:number;total:number;percent:number}>;
  assert.ok(progress.length>0 && progress.every(p=>p.loaded<=p.total && p.percent>=0 && p.percent<=100));
  await page.evaluate("result.forget()");assert.equal(await page.evaluate("localStorage.length"),0);
  feature=false;await page.evaluate("begin()");assert.equal((await page.evaluate<BrowserResult>("work")).fallback,true);feature=true;
  assert.deepEqual(errors,[]);checks.push(`${engine}: real Blob/XHR signed lengths; pause, page reload, saved-part resume, no secret cache, progress bounds, explicit disabled-provider fallback`);
  console.log("PASS",checks.at(-1));await browser.close();browser=undefined;
 }
 writeFileSync(".data/qa-resumable-browser-report.json",JSON.stringify({passed:checks.length,checks,devices:"actual browser engines, not physical phones",provider:"local HTTP S3 double",authentication:"synthetic loopback HTTP boundary; actual adminFetch binds actor"},null,2));
}finally{
 await browser?.close(); if(ownerIds.length){await db.delete(schema.videoUploadSessions).where(inArray(schema.videoUploadSessions.userId,ownerIds));await db.delete(schema.users).where(inArray(schema.users.id,ownerIds));}
 await closeDb();await new Promise<void>((resolve,reject)=>{server.close(err=>err?reject(err):resolve());server.closeAllConnections();});await s3.close();
}
